const item = $input.first().json;
const monitor = item.body?.monitor ?? {};
const rawContainer = monitor.docker_container || monitor.name || '';
const container = String(rawContainer).trim().toLowerCase();

if (!/^[a-z0-9][a-z0-9_.-]*$/.test(container)) {
  throw new Error(`Invalid Docker container name: ${rawContainer}`);
}

return [{ json: { ...item, container } }];
